span.style:
color: var(--text-dim);
font-size: 0.8rem;
display: inline-block;
margin-top: 6px;

body.script:
//
// === Module: 01_utils.js ===
// SHA-256 Constant
      const RELEASE_SHA256 =
        "ECFF39F3358CC29307CE77AE5AA8B1653010998E08574ED74F87807A97061EA8";

      // Toast helper
      function showToast(message, icon = "✅") {
        const toast = document.getElementById("toast");
        const msg = document.getElementById("toast-msg");
        const ico = document.getElementById("toast-icon");
        if (!toast) return;

        msg.innerText = message;
        ico.innerText = icon;
        toast.classList.add("show");

        setTimeout(() => {
          toast.classList.remove("show");
        }, 3000);
      }

      // Copy checksum
      function copyChecksum() {
        navigator.clipboard
          .writeText(RELEASE_SHA256)
          .then(() => {
            showToast("Đã chép mã băm SHA-256 vào clipboard!", "📋");
          })
          .catch(() => {
            showToast(RELEASE_SHA256, "📋");
          });
      }

      const copyShaBtn = document.getElementById("copy-sha-btn");
      if (copyShaBtn) {
        copyShaBtn.addEventListener("click", copyChecksum);
      }

// === Module: 02_simulator.js ===
/* ==========================================================================
       CHKEY TELEX IN-BROWSER SIMULATOR ENGINE
       Implements exact rules matching chkey_engine (Êđê / Tây Nguyên)
       ========================================================================== */
      const simInput = document.getElementById("sim-input");
      const charCount = document.getElementById("char-count");

      // Mapping table for 2-key and 3-key combinations
      const TELEX_MAP = {
        // Phụ âm
        bb: "ƀ",
        BB: "Ƀ",
        Bb: "ƀ",
        bB: "ƀ",
        cx: "č",
        CX: "Č",
        Cx: "č",
        cX: "č",
        nn: "ñ",
        NN: "Ñ",
        Nn: "ñ",
        nN: "ñ",
        dd: "đ",
        DD: "Đ",
        Dd: "đ",
        dD: "đ",

        // Nguyên âm có dấu trăng (Breve)
        ax: "ă",
        AX: "Ă",
        Ax: "ă",
        aX: "ă",
        ex: "ĕ",
        EX: "Ĕ",
        Ex: "ĕ",
        eX: "ĕ",
        ix: "ĭ",
        IX: "Ĭ",
        Ix: "ĭ",
        iX: "ĭ",
        ox: "ŏ",
        OX: "Ŏ",
        Ox: "ŏ",
        oX: "ŏ",
        ux: "ŭ",
        UX: "Ŭ",
        Ux: "ŭ",
        uX: "ŭ",

        // Nguyên âm nón (Circumflex)
        aa: "â",
        AA: "Â",
        Aa: "â",
        aA: "â",
        ee: "ê",
        EE: "Ê",
        Ee: "ê",
        eE: "ê",
        oo: "ô",
        OO: "Ô",
        Oo: "ô",
        oO: "ô",

        // Nguyên âm móc (Horn)
        ow: "ơ",
        OW: "Ơ",
        Ow: "ơ",
        oW: "ơ",
        uw: "ư",
        UW: "Ư",
        Uw: "ư",
        uW: "ư",
        uu: "ư",
        UU: "Ư",
        Uu: "ư",
        uU: "ư",

        // Nguyên âm đôi trăng kết hợp
        âx: "â̆",
        Âx: "Â̆",
        âX: "â̆",
        ÂX: "Â̆",
        êx: "ê̆",
        Êx: "Ê̆",
        êX: "ê̆",
        ÊX: "Ê̆",
        ôx: "ô̆",
        Ôx: "Ô̆",
        ôX: "ô̆",
        ÔX: "Ô̆",
        ơx: "ơ̆",
        Ơx: "Ơ̆",
        ơX: "ơ̆",
        ƠX: "Ơ̆",
        ưx: "ư̆",
        Ưx: "Ư̆",
        ưX: "ư̆",
        ƯX: "Ư̆",
      };

      if (simInput) {
        simInput.addEventListener("input", function (e) {
          let val = simInput.value;
          let pos = simInput.selectionStart;

          // Check 2-letter combos right before cursor
          if (pos >= 2) {
            let slice2 = val.substring(pos - 2, pos);
            if (TELEX_MAP[slice2]) {
              let repl = TELEX_MAP[slice2];
              simInput.value =
                val.substring(0, pos - 2) + repl + val.substring(pos);
              simInput.selectionStart = simInput.selectionEnd = pos - 1;
              updateCharCount();
              return;
            }
          }

          // Check 3-letter combos (e.g. aax -> â̆, eex -> ê̆, oox -> ô̆, owx -> ơ̆, uwx -> ư̆)
          if (pos >= 3) {
            let slice3 = val.substring(pos - 3, pos);
            const THREE_MAP = {
              aax: "â̆",
              AAX: "Â̆",
              Aax: "â̆",
              eex: "ê̆",
              EEX: "Ê̆",
              Eex: "ê̆",
              oox: "ô̆",
              OOX: "Ô̆",
              Oox: "ô̆",
              owx: "ơ̆",
              OWX: "Ơ̆",
              Owx: "ơ̆",
              uwx: "ư̆",
              UWX: "Ư̆",
              Uwx: "ư̆",
            };
            if (THREE_MAP[slice3]) {
              let repl = THREE_MAP[slice3];
              simInput.value =
                val.substring(0, pos - 3) + repl + val.substring(pos);
              simInput.selectionStart = simInput.selectionEnd = pos - 2;
              updateCharCount();
              return;
            }
          }

          updateCharCount();
        });
      }

      function updateCharCount() {
        if (!simInput || !charCount) return;
        charCount.innerText = `${simInput.value.length} ký tự`;
      }

      // Insert sample into simulator
      function insertSample(text) {
        if (!simInput) return;
        simInput.value = text + " ";
        simInput.focus();
        updateCharCount();
        showToast(`Đã nạp mẫu: "${text}"`, "✍️");
      }

      // Clear simulator
      function clearSim() {
        if (!simInput) return;
        simInput.value = "";
        simInput.focus();
        updateCharCount();
      }

      // Insert single character from virtual palette
      function insertChar(ch) {
        if (!simInput) return;
        const start = simInput.selectionStart || simInput.value.length;
        const end = simInput.selectionEnd || simInput.value.length;
        const text = simInput.value;
        simInput.value = text.substring(0, start) + ch + text.substring(end);
        simInput.selectionStart = simInput.selectionEnd = start + ch.length;
        simInput.focus();
        updateCharCount();
        showToast(`Đã chèn ký tự: ${ch}`, "✨");
      }

// === Module: 03_guide.js ===
// Switch Guide Tabs between Windows and macOS
      function switchGuide(os) {
        const winTab = document.getElementById("tab-guide-win");
        const macTab = document.getElementById("tab-guide-mac");
        const winSteps = document.getElementById("guide-win-steps");
        const macSteps = document.getElementById("guide-mac-steps");

        if (!winTab || !macTab || !winSteps || !macSteps) return;

        if (os === "mac") {
          winTab.classList.remove("active");
          winTab.setAttribute("aria-selected", "false");
          macTab.classList.add("active");
          macTab.setAttribute("aria-selected", "true");
          winSteps.classList.remove("active");
          macSteps.classList.add("active");
        } else {
          macTab.classList.remove("active");
          macTab.setAttribute("aria-selected", "false");
          winTab.classList.add("active");
          winTab.setAttribute("aria-selected", "true");
          macSteps.classList.remove("active");
          winSteps.classList.add("active");
        }
      }

// === Module: 04_detect_os.js ===
// Auto-detect OS to highlight appropriate download button
      (function detectOS() {
        const isMac =
          /Macintosh|MacIntel|MacPPC|Mac68K|Mac/i.test(navigator.userAgent) ||
          (navigator.platform &&
            navigator.platform.toUpperCase().indexOf("MAC") >= 0);
        if (isMac) {
          switchGuide("mac");
          const chipWin = document.getElementById("chip-win");
          const chipMacArm = document.getElementById("chip-mac-arm");
          const macBtn = document.getElementById("hero-download-mac-btn");
          const winBtn = document.getElementById("hero-download-btn");
          const cardWin = document.getElementById("card-win-x64");
          const cardMac = document.getElementById("card-mac-arm");

          if (chipWin) chipWin.classList.remove("active");
          if (chipMacArm) chipMacArm.classList.add("active");
          if (cardWin) cardWin.classList.remove("primary-hub");
          if (cardMac) cardMac.classList.add("primary-hub");

          if (macBtn && winBtn) {
            macBtn.style.order = "-1";
            macBtn.style.boxShadow = "0 10px 30px rgba(56, 189, 248, 0.4)";
            macBtn.style.borderColor = "#38bdf8";
          }

          const badge = document.querySelector(".badge-pill");
          if (badge) {
            badge.innerHTML = `<span class="badge-dot"></span> Đã nhận diện hệ điều hành: macOS • Bản v1.0.0`;
          }
        }
      })();
//
